solution.solution.cpp:
void minMax(int a, int b, int c, int& smallest, int& largest)
{
    smallest = a;
    largest = a;
    if (b < smallest) smallest = b;
    if (c < smallest) smallest = c;
    if (b > largest) largest = b;
    if (c > largest) largest = c;
}

unitTests:
TEST("three different numbers") { int lo{}, hi{}; minMax(8, 3, 5, lo, hi); CHECK_EQ(lo, 3); CHECK_EQ(hi, 8); }
TEST("already in order") { int lo{}, hi{}; minMax(1, 2, 3, lo, hi); CHECK_EQ(lo, 1); CHECK_EQ(hi, 3); }
TEST("negatives and ties") { int lo{ 99 }, hi{ 99 }; minMax(-4, -4, -9, lo, hi); CHECK_EQ(lo, -9); CHECK_EQ(hi, -4); }

